import {useEffect, useMemo, useRef, useState, type Dispatch, type SetStateAction} from 'react';
import {
  TRAINING_DAYS, TRAINING_WEEKS, TRAINING_EXERCISES, createTrainingSession,
  updateTrainingSet, completeTrainingSet, pauseTrainingSession, resumeTrainingSession,
  finishTrainingSession, getTrainingElapsed, getRestRemaining, getPreviousExercise,
  getTrainingSummary, changeTrainingVariant, addTrainingSet, removeTrainingSet,
  getSetRemaining, startTrainingSetTimer, isTimedTrainingExercise, importLegacyTraining, normalizeTrainingRoutine,
  type TrainingSession, type TrainingExerciseLog, type TrainingExerciseDefinition, type TrainingRoutine, type LegacyTrainingImport,
} from '../lib/training';
import {getTrainingMedia, getTrainingTutorial, getTrainingIllustration} from '../lib/trainingMedia';
import {getDateAccess} from '../lib/datePolicy';
import {useDateAccess} from '../lib/useDateAccess';
import {isAndroidTrainingTimers} from '../lib/trainingAlarms';
import './training.css';

type Sessions = Record<string, TrainingSession>;
type Routines = Record<string, TrainingRoutine>;
export type TrainingProps = {
  sessions: Sessions;
  setSessions: Dispatch<SetStateAction<Sessions>>;
  routines: Routines;
  setRoutines: Dispatch<SetStateAction<Routines>>;
  selectedDate: string;
  onComplete: (date: string) => void;
  scope?: string;
  hidden?: boolean;
  entryRequest?: number;
  onAdjustSchedule?: () => void;
  onGoToday?: () => void;
  onImportLegacy?: (result:LegacyTrainingImport) => void;
  scheduledMinutes?: number;
  timerWarning?: string|null;
  onReviewAlarms?:()=>void;
};
const newId = (prefix: string) => `${prefix}-${crypto.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`}`;
const clock = (seconds: number) => `${String(Math.floor(Math.max(0, seconds) / 60)).padStart(2, '0')}:${String(Math.floor(Math.max(0, seconds)) % 60).padStart(2, '0')}`;
const dateLabel = (date: string) => new Date(`${date}T12:00:00`).toLocaleDateString('es-AR', {day:'numeric', month:'short'});
const optionalNumber = (value: string) => value.trim() === '' ? null : Number(value);
const boundedNumber=(value:string,min:number,max:number,integer=false)=>{const number=optionalNumber(value);return number===null?null:Number.isFinite(number)?Math.min(max,Math.max(min,integer?Math.round(number):number)):null;};
const statusLabel = {active:'En curso', paused:'En pausa', completed:'Finalizada', abandoned:'Interrumpida', imported:'Importada'};
const exerciseLabel = {pending:'Pendiente', done:'Hecho', adjust:'Ajustar', skipped:'Saltado'};

function TrainingIcon({name, size=20}:{name:'play'|'pause'|'check'|'arrow'|'back'|'clock'|'plus'|'gym'|'chart'|'close';size?:number}) {
  const paths = {play:<path d="m9 5 11 7-11 7z"/>,pause:<path d="M8 5v14M16 5v14"/>,check:<path d="m5 12 4 4L19 6"/>,arrow:<path d="M5 12h14m-6-6 6 6-6 6"/>,back:<path d="M19 12H5m6-6-6 6 6 6"/>,clock:<><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>,plus:<path d="M12 5v14M5 12h14"/>,gym:<path d="m6 6 12 12M3 9l6-6m6 18 6-6M2 6l4-4m12 20 4-4"/>,chart:<path d="M4 4v16h16M8 15l4-5 4 2 4-7"/>,close:<path d="m6 6 12 12M6 18 18 6"/>};
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>;
}

export function Training({sessions, setSessions, routines, setRoutines, selectedDate, onComplete, scope, hidden=false, entryRequest=0, onAdjustSchedule, onGoToday, onImportLegacy, scheduledMinutes,timerWarning,onReviewAlarms}:TrainingProps) {
  const [view, setView] = useState<'session'|'history'|'custom'>('session');
  const [week, setWeek] = useState<1|2|3|4>(()=>Object.values(sessions).sort((a,b)=>b.startedAt-a.startedAt)[0]?.week??1);
  const [day, setDay] = useState<1|2|3>(()=>{const last=Object.values(sessions).sort((a,b)=>b.startedAt-a.startedAt)[0];return last?((last.status==='completed'?last.day%3+1:last.day) as 1|2|3):1;});
  const [routineId, setRoutineId] = useState('');
  const [sessionId, setSessionId] = useState('');
  const [exerciseCursor, setExerciseCursor] = useState<{sessionId:string;index:number}|null>(null);
  const [now, setNow] = useState(Date.now());
  const [message, setMessage] = useState('');
  const [endDialog, setEndDialog] = useState<'finish'|'abandon'|null>(null);
  const [correction,setCorrection]=useState<{sessionId:string;exerciseIndex:number;setId:string}|null>(null);
  const [preview, setPreview] = useState<string|null>(null);
  const [historyExercise, setHistoryExercise] = useState(TRAINING_EXERCISES[0].id);
  const restAlert = useRef<string>('');
  const previousRest = useRef<number>(0);
  const audioContext = useRef<AudioContext|null>(null);
  const selectedAccess = useDateAccess(selectedDate);
  const today = selectedAccess.today;
  const datedSessions = useMemo(()=>Object.values(sessions).filter(s=>s.date===selectedDate).sort((a,b)=>b.startedAt-a.startedAt),[sessions,selectedDate]);
  const active = datedSessions.find(s=>s.status==='active'||s.status==='paused');
  const todayActive = Object.values(sessions).filter(s=>s.date===today&&(s.status==='active'||s.status==='paused')).sort((a,b)=>b.startedAt-a.startedAt)[0];
  const session = sessionId ? sessions[sessionId] : active ?? (selectedAccess.kind==='past'?datedSessions[0]:undefined);
  const running = Boolean(session && ['active','paused'].includes(session.status));
  const sessionAccess = useDateAccess(session?.date??selectedDate);
  const canEditSession = Boolean(session && selectedAccess.canExecute && sessionAccess.canExecute && session.status!=='imported');
  const editableRunning = running && canEditSession;
  const exerciseIndex = session ? !canEditSession && exerciseCursor?.sessionId===session.id ? Math.min(exerciseCursor.index,session.exercises.length-1) : session.currentExercise : 0;
  const exercise = session?.exercises[exerciseIndex];
  const timedExercise = exercise ? isTimedTrainingExercise(exercise) : false;
  const definition = exercise ? TRAINING_EXERCISES.find(e=>e.id===exercise.exerciseId) ?? Object.values(routines).flatMap(r=>r.exercises).find(e=>e.id===exercise.exerciseId) : undefined;
  const dayPlan = TRAINING_DAYS.find(d=>d.day===day)!;
  const chosenRoutine = routines[routineId];
  const plannedExercises = chosenRoutine?.exercises ?? dayPlan.exercises;
  const previous = exercise ? getPreviousExercise(sessions, exercise.exerciseId, exercise.variantId, session?.id) : undefined;
  const summary = session ? getTrainingSummary(session) : null;
  const rest = session ? getRestRemaining(session, Math.max(now,Date.now())) : 0;
  const restActive = Boolean(session && (session.restUntil!==null||session.pausedRestSeconds!==null));

  useEffect(()=>{setSessionId('');setExerciseCursor(null);setView('session');setEndDialog(null);setCorrection(null);setMessage('');setPreview(null);restAlert.current='';},[scope,selectedDate]);
  useEffect(()=>{if(entryRequest){setView('session');setSessionId(active?.id??'');setPreview(null);}},[entryRequest]);
  useEffect(()=>{setNow(Date.now());if(hidden&&!active)return;const tick=window.setInterval(()=>setNow(Date.now()),1000);return()=>window.clearInterval(tick);},[hidden,active?.id,active?.status]);
  useEffect(()=>{if(!canEditSession){setEndDialog(null);setCorrection(null);}},[canEditSession]);
  useEffect(()=>{if(!message)return;const timeout=window.setTimeout(()=>setMessage(''),6000);return()=>window.clearTimeout(timeout);},[message]);
  useEffect(()=>{
    if(!hidden&&view==='session'&&canEditSession&&session?.status==='active'&&getDateAccess(selectedDate).canExecute&&getDateAccess(session.date).canExecute&&restActive&&rest===0&&previousRest.current>0){
      const key=`${session.id}:${session.restUntil}`;
      if(restAlert.current!==key){restAlert.current=key;setMessage('Descanso listo. Volvé a tu próxima serie cuando estés preparado.');
        if(!isAndroidTrainingTimers())try{const ctx=audioContext.current;if(ctx&&ctx.state!=='closed'){void ctx.resume();const sound=ctx.createOscillator();const gain=ctx.createGain();sound.type='sine';sound.frequency.value=660;gain.gain.setValueAtTime(.001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.08,ctx.currentTime+.03);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.4);sound.connect(gain);gain.connect(ctx.destination);sound.start();sound.stop(ctx.currentTime+.42);}}catch{/* Visual completion remains available. */}
      }
    }
    previousRest.current=rest;
  },[rest,restActive,session?.id,session?.status,session?.restUntil,hidden,view,canEditSession,selectedDate]);
  useEffect(()=>()=>{void audioContext.current?.close();},[]);

  function unlockAudio(){if(isAndroidTrainingTimers())return;try{if(!audioContext.current)audioContext.current=new AudioContext();void audioContext.current.resume();}catch{/* Some devices only support the visual timer. */}}
  function canExecuteSession(current:TrainingSession){return getDateAccess(selectedDate).canExecute&&getDateAccess(current.date).canExecute&&current.status!=='imported';}
  function changeSession(change:(current:TrainingSession)=>TrainingSession){if(!session||!canExecuteSession(session))return;setSessions(all=>{const current=all[session.id];return current&&canExecuteSession(current)?{...all,[session.id]:change(current)}:all;});}
  function patchExercise(patch:Partial<TrainingExerciseLog>){changeSession(s=>({...s,exercises:s.exercises.map((item,index)=>index===exerciseIndex?{...item,...patch}:item)}));}
  function start(){
    if(!getDateAccess(selectedDate).canExecute)return;
    if(active){setSessionId(active.id);setView('session');setMessage('Retomamos tu sesión guardada.');return;}
    const next=createTrainingSession({id:newId('gym'),date:selectedDate,week,day,sessions,now:Date.now(),...(chosenRoutine?{routine:chosenRoutine}:{})});
    setSessions(all=>getDateAccess(selectedDate).canExecute?{...all,[next.id]:next}:all);setSessionId(next.id);setExerciseCursor(null);setView('session');unlockAudio();
  }
  function finish(){
    if(!session||!canExecuteSession(session))return;
    changeSession(s=>finishTrainingSession(s,Date.now(),endDialog==='abandon'?'abandoned':'completed'));
    if(endDialog==='finish'&&session.exercises.some(e=>e.sets.some(s=>s.kind==='working'&&s.completedAt!==null)))onComplete(session.date);
    setEndDialog(null);setMessage(endDialog==='abandon'?'Lo registrado queda en tu historial.':'Sesión guardada. Tu próxima vez empieza desde acá.');
  }
  function beginRest(seconds:number){if(!session||!canExecuteSession(session))return;unlockAudio();changeSession(s=>({...s,restUntil:s.status==='active'?Date.now()+seconds*1000:null,pausedRestSeconds:s.status==='paused'?seconds:null}));}
  function showExercise(index:number){if(!session||index<0||index>=session.exercises.length)return;setExerciseCursor({sessionId:session.id,index});if(canExecuteSession(session))changeSession(s=>index===s.currentExercise?s:{...s,currentExercise:index,setTimerUntil:null,pausedSetSeconds:null});setPreview(null);}

  return <div className="mv-training" hidden={hidden}>
    {timerWarning&&<div className="gym-date-lock" role="status"><TrainingIcon name="clock" size={20}/><div><strong>Revisá el sonido del entrenamiento</strong><p>{timerWarning}</p>{onReviewAlarms&&<button className="text-button" onClick={onReviewAlarms}>Revisar permisos en Alarmas</button>}</div></div>}
    <div className="page-title"><div><p className="eyebrow">UN RATO PARA TU CUERPO</p><h1>Entrená a tu ritmo<span>.</span></h1><p className="subtitle">Tu rutina, tus descansos y cada pequeño avance, en un solo lugar.</p></div><span className="gym-brand-mark"><TrainingIcon name="gym" size={30}/></span></div>
    <nav className="gym-view-nav" aria-label="Herramientas de entrenamiento">{([{id:'session',name:'Entrenar',icon:'gym'},{id:'history',name:'Mi progreso',icon:'chart'},{id:'custom',name:'Mis rutinas',icon:'plus'}] as const).map(item=><button key={item.id} aria-current={view===item.id?'page':undefined} className={view===item.id?'active':''} onClick={()=>{setView(item.id);setEndDialog(null);}}><TrainingIcon name={item.icon} size={18}/>{item.name}</button>)}</nav>
    {view==='session'&&(!selectedAccess.canExecute||(session&&!canEditSession))&&<div className="gym-date-lock" role="status"><TrainingIcon name="clock" size={20}/><div><strong>{selectedAccess.kind==='future'?'Una vista de lo que viene.':'Este día es de solo consulta.'}</strong><p>{selectedAccess.kind==='future'?'Podés explorar rutinas y tutoriales. Las series, las cargas y los cronómetros se habilitan el mismo día.':session?.status==='imported'?'El registro importado conserva sus datos originales.':'Los días pasados quedan cerrados: sus registros, notas y cargas se conservan sin cambios.'}</p></div>{todayActive&&onGoToday&&<button className="button secondary" onClick={()=>{setSessionId('');setExerciseCursor(null);onGoToday();}}>Volver al entrenamiento de hoy<TrainingIcon name="arrow" size={16}/></button>}</div>}
    {message&&<div className="gym-message" role="status">{message}<button aria-label="Cerrar aviso" onClick={()=>setMessage('')}><TrainingIcon name="close" size={17}/></button></div>}
    {view==='session'&&editableRunning&&session&&restActive&&<section className="gym-compact-rest" aria-label="Descanso en curso" aria-live="off"><TrainingIcon name="clock" size={19}/><span><small>{rest===0?'Listo para seguir':session.status==='paused'||session.restUntil===null?'En pausa':'Descanso'}</small><strong role="timer" aria-live="off">{clock(rest)}</strong></span><button aria-label={session.status==='paused'||session.restUntil===null?'Seguir descanso':'Pausar descanso'} disabled={rest===0} onClick={()=>changeSession(s=>s.status==='paused'?resumeTrainingSession(s,Date.now()):s.restUntil!==null?{...s,pausedRestSeconds:getRestRemaining(s,Date.now()),restUntil:null}:{...s,restUntil:Date.now()+(s.pausedRestSeconds??0)*1000,pausedRestSeconds:null})}><TrainingIcon name={session.status==='paused'||session.restUntil===null?'play':'pause'} size={17}/><span>{session.status==='paused'||session.restUntil===null?'Seguir':'Pausar'}</span></button><button aria-label="Saltar descanso" onClick={()=>changeSession(s=>({...s,restUntil:null,pausedRestSeconds:null}))}>Saltar</button></section>}
    {view==='session'&&<>
      {session&&<div className="gym-session-toolbar"><button className="text-button" onClick={()=>{setSessionId('');if(active?.id===session.id)setView('history');}}>‹ Ver mis entrenamientos</button><span>{session.status==='imported'?'Fecha de entrenamiento no registrada':dateLabel(session.date)} · {statusLabel[session.status]} · {clock(getTrainingElapsed(session,now))}</span></div>}
      {session&&exercise ? <>
        <div className="gym-session-top"><div><p className="eyebrow">SEMANA {session.week} · {session.title}</p><h2>Una serie a la vez.</h2></div><div className="gym-session-actions">{editableRunning&&<button className="button secondary" onClick={()=>{if(!canExecuteSession(session))return;unlockAudio();changeSession(s=>s.status==='paused'?resumeTrainingSession(s,Date.now()):pauseTrainingSession(s,Date.now()));}}><TrainingIcon name={session.status==='paused'?'play':'pause'} size={16}/>{session.status==='paused'?'Reanudar':'Pausar'}</button>}{editableRunning&&<button className="button primary" onClick={()=>{if(canExecuteSession(session))setEndDialog('finish');}}>Terminar<TrainingIcon name="check" size={16}/></button>}</div></div>
        <div className="gym-session-progress"><span style={{width:`${session.exercises.length?session.exercises.filter(e=>e.status==='done'||e.status==='skipped').length/session.exercises.length*100:0}%`}}/></div>
        <div className="gym-progress-caption"><span>{session.exercises.filter(e=>e.status==='done').length}/{session.exercises.length} ejercicios hechos</span><span>{summary?.completedSets??0} series registradas</span></div>
        {session.status==='paused'&&<div className="gym-paused" role="status"><TrainingIcon name="pause"/>Sesión en pausa. Tus series y descansos están guardados.</div>}
        <div className="gym-session-layout">
          <section className="gym-exercise-card" aria-label="Ejercicio actual">
            <div className="gym-exercise-art"><img src={import.meta.env.BASE_URL+getTrainingIllustration(exercise.exerciseId,exercise.variantId)} alt="" width="520" height="260"/><span className="gym-exercise-counter">{exerciseIndex+1} de {session.exercises.length}</span><span className={'gym-state-chip '+exercise.status}>{exerciseLabel[exercise.status]}</span></div>
            <div className="gym-exercise-body"><p className="eyebrow">{exercise.primaryMuscle}</p><h2>{exercise.name}</h2>
              {definition&&definition.variants.length>1&&<label className="gym-variant"><span>{canEditSession?'Variante de hoy':'Variante registrada'}</span><select aria-label="Variante del ejercicio" disabled={!editableRunning||exercise.sets.some(s=>s.completedAt!==null)} value={exercise.variantId} onChange={event=>changeSession(s=>changeTrainingVariant(s,exerciseIndex,event.target.value,sessions))}>{definition.variants.map(variant=><option key={variant.id} value={variant.id}>{variant.name}</option>)}</select><small>Las cargas se recuerdan por variante. Cambiá antes de completar series.</small></label>}
              <div className="gym-prescription"><span><strong>{exercise.targetSets}</strong> series</span><span><strong>{timedExercise?`${exercise.secondsTarget??30} s`:`${exercise.repsMin}–${exercise.repsMax}`}</strong>{timedExercise?'por serie':'repeticiones'}</span><span><strong>{exercise.restSeconds} s</strong> de descanso</span></div>
              <Tutorial exercise={exercise} preview={preview} setPreview={setPreview}/>
              {previous&&<PreviousLoad previous={previous}/>}
              {exercise.hasWarmupSet&&<div className="gym-warmup-cue"><span>S0</span><div><strong>Primero, una aproximación.</strong><small>Carga moderada para preparar el movimiento. Se registra por separado.</small></div></div>}
              <div className="gym-sets" aria-label="Series del ejercicio">{exercise.sets.map((set,index)=><div key={set.id} className={'gym-set-row '+(set.kind==='warmup'?'warmup ':'')+(set.completedAt!==null?'is-done':'')}>
                <div className="gym-set-label"><span>{set.kind==='warmup'?'S0':`S${exercise.sets.filter((s,i)=>i<=index&&s.kind==='working').length}`}</span><small>{set.kind==='warmup'?'Aproximación':set.completedAt!==null?'Registrada':'Efectiva'}</small></div>
                <label><span>kg</span><input aria-label={`Carga ${set.id.toUpperCase()}`} type="number" inputMode="decimal" min="0" max="1500" step="0.5" placeholder="—" value={set.loadKg??''} disabled={!editableRunning||session.status==='paused'||set.completedAt!==null} onChange={e=>changeSession(s=>updateTrainingSet(s,exerciseIndex,set.id,{loadKg:boundedNumber(e.target.value,0,1500)},Date.now()))}/></label>
                <label><span>{timedExercise?'segundos':'reps'}</span><input aria-label={`${timedExercise?'Segundos':'Repeticiones'} ${set.id.toUpperCase()}`} type="number" inputMode="numeric" min="0" max={timedExercise?'7200':'1000'} step="1" placeholder={timedExercise?String(exercise.secondsTarget):`${exercise.repsMin}–${exercise.repsMax}`} value={(timedExercise?set.durationSeconds:set.reps)??''} disabled={!editableRunning||session.status==='paused'||set.completedAt!==null} onChange={e=>changeSession(s=>updateTrainingSet(s,exerciseIndex,set.id,timedExercise?{durationSeconds:boundedNumber(e.target.value,0,7200,true)}:{reps:boundedNumber(e.target.value,0,1000,true)},Date.now()))}/></label>
                <button className="gym-set-check" disabled={!canEditSession||session.status==='paused'||(!running&&(session.status==='imported'||set.completedAt===null))||(set.completedAt===null&&((set.kind==='working'&&exercise.sets.some(s=>s.kind==='warmup'&&s.completedAt===null))||!(timedExercise?(set.durationSeconds??0)>0:(set.reps??0)>0)))} title={set.kind==='working'&&exercise.sets.some(s=>s.kind==='warmup'&&s.completedAt===null)?'Primero completá la aproximación':undefined} aria-label={!canEditSession?`${set.id.toUpperCase()} · ${set.completedAt!==null?'Registrada':'Pendiente'} · solo consulta`:set.completedAt!==null?`Corregir ${set.id.toUpperCase()} registrada`:`Completar ${set.id.toUpperCase()} e iniciar descanso`} onClick={()=>{if(!canExecuteSession(session))return;if(set.completedAt!==null){if(!running){setCorrection({sessionId:session.id,exerciseIndex,setId:set.id});return;}patchExercise({sets:exercise.sets.map(item=>item.id===set.id?{...item,completedAt:null}:item),status:exercise.status==='done'?'pending':exercise.status});return;}unlockAudio();changeSession(s=>completeTrainingSet(s,exerciseIndex,set.id,Date.now()));}}>{set.completedAt!==null?<><TrainingIcon name="check" size={16}/><span>{canEditSession?'Editar':'Registrada'}</span></>:<><span>Listo</span><TrainingIcon name="check" size={17}/></>}</button>
              </div>)}</div>
              {editableRunning&&<div className="gym-set-tools">{exercise.sets.filter(s=>s.kind==='working').length<4&&<button className="text-button" onClick={()=>changeSession(s=>addTrainingSet(s,exerciseIndex,'working'))}>+ Serie efectiva</button>}{!exercise.sets.some(s=>s.kind==='warmup')&&<button className="text-button" onClick={()=>changeSession(s=>addTrainingSet(s,exerciseIndex,'warmup'))}>+ Aproximación opcional</button>}{exercise.sets.length>1&&exercise.sets.at(-1)?.completedAt===null&&<button className="text-button" onClick={()=>changeSession(s=>removeTrainingSet(s,exerciseIndex,exercise.sets.at(-1)!.id))}>Quitar última sin completar</button>}</div>}
              {timedExercise&&editableRunning&&<SetCountdown session={session} exercise={exercise} now={now} changeSession={changeSession}/>}
              <details className="gym-details"><summary>Técnica y cómo se sintió</summary>{definition?.instructions&&<p>{definition.instructions}</p>}<div className="gym-feedback"><label><span>Esfuerzo · RPE 1–10</span><input type="number" inputMode="decimal" min="1" max="10" step="0.5" disabled={!canEditSession} value={exercise.rpe??''} onChange={e=>patchExercise({rpe:boundedNumber(e.target.value,1,10)})}/></label><label><span>Molestia · 0–10</span><input type="number" inputMode="numeric" min="0" max="10" disabled={!canEditSession} value={exercise.discomfort??''} onChange={e=>patchExercise({discomfort:boundedNumber(e.target.value,0,10)})}/></label><label><span>Estado</span><select disabled={!canEditSession} value={exercise.status} onChange={e=>patchExercise({status:e.target.value as TrainingExerciseLog['status']})}>{Object.entries(exerciseLabel).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label></div><label className="gym-note-label"><span>Tu nota para la próxima vez</span><textarea rows={3} maxLength={3000} readOnly={!canEditSession} value={exercise.notes} placeholder="Técnica, sensaciones, ajustes…" onChange={e=>patchExercise({notes:e.target.value})}/></label></details>
              <div className="gym-exercise-navigation"><button className="button secondary" disabled={exerciseIndex===0} onClick={()=>showExercise(exerciseIndex-1)}><TrainingIcon name="back" size={16}/>Anterior</button>{editableRunning&&exercise.status!=='done'&&exercise.status!=='skipped'&&<button className="text-button" onClick={()=>{patchExercise({status:'skipped'});if(exerciseIndex<session.exercises.length-1)showExercise(exerciseIndex+1);}}>Saltar</button>}<button className="button primary" disabled={exerciseIndex===session.exercises.length-1} onClick={()=>showExercise(exerciseIndex+1)}>Siguiente<TrainingIcon name="arrow" size={16}/></button></div>
            </div>
          </section>
          <aside className="gym-session-aside"><RestTimer session={session} now={now} canEdit={editableRunning} exerciseIndex={exerciseIndex} changeSession={changeSession} beginRest={beginRest}/><section className="gym-queue"><div className="gym-panel-heading"><p className="eyebrow">TU RECORRIDO</p><span>{session.exercises.length} ejercicios</span></div>{session.exercises.map((item,index)=><button key={item.exerciseId} className={index===exerciseIndex?'current':''} aria-current={index===exerciseIndex?'step':undefined} onClick={()=>showExercise(index)}><span className={'gym-queue-index '+item.status}>{item.status==='done'?<TrainingIcon name="check" size={15}/>:index+1}</span><span><strong>{item.name}</strong><small>{item.sets.filter(s=>s.kind==='working'&&s.completedAt!==null).length}/{item.targetSets} series · {exerciseLabel[item.status]}</small></span><span>›</span></button>)}</section></aside>
        </div>
        <label className="gym-session-note gym-note-label"><span>Una nota de este entrenamiento</span><textarea rows={2} maxLength={3000} readOnly={!canEditSession} value={session.notes} placeholder="Cómo llegaste, qué cambió, qué querés recordar…" onChange={e=>changeSession(s=>({...s,notes:e.target.value}))}/></label>
        {editableRunning&&<button className="text-button gym-abandon" onClick={()=>{if(canExecuteSession(session))setEndDialog('abandon');}}>Interrumpir sesión y conservar lo registrado</button>}
      </> : <>
        <section className="gym-welcome"><div><p className="eyebrow">TU PLAN, AHORA EN MI VIDA.</p><h2>Hacete este espacio.</h2><p>Entrás, hacés una serie y descansás. Nosotros recordamos dónde quedaste.</p><button className="button lime" disabled={!selectedAccess.canExecute} onClick={start}><TrainingIcon name="play" size={18}/>{!selectedAccess.canExecute?'Solo consulta':active?'Retomar sesión':'Empezar entrenamiento'}</button><small>{dateLabel(selectedDate)} · Tu registro acompaña a tu cuenta</small></div><img src={import.meta.env.BASE_URL+getTrainingIllustration(plannedExercises[0]?.id??'d1-e1')} width="310" height="250" alt=""/></section>
        {scheduledMinutes!==undefined&&<div className="gym-schedule-note"><span><TrainingIcon name="clock" size={17}/>{scheduledMinutes} minutos reservados en tu agenda</span>{onAdjustSchedule&&selectedAccess.canPlan&&<button className="text-button" onClick={onAdjustSchedule}>Ajustar horario ↗</button>}</div>}
        <div className="gym-plan-selectors"><label><span>Semana de la rutina</span><select value={week} onChange={e=>setWeek(Number(e.target.value) as typeof week)}>{TRAINING_WEEKS.map(item=><option key={item.week} value={item.week}>Semana {item.week} · {item.focus}</option>)}</select></label><label><span>{selectedAccess.canExecute?'Rutina de hoy':'Explorar una rutina'}</span><select value={routineId||String(day)} onChange={e=>{if(['1','2','3'].includes(e.target.value)){setDay(Number(e.target.value) as typeof day);setRoutineId('');}else setRoutineId(e.target.value);}}>{TRAINING_DAYS.map(item=><option key={item.day} value={item.day}>Día {item.day} · {item.title}</option>)}{Object.values(routines).map(item=><option key={item.id} value={item.id}>{item.name} · Personal</option>)}</select></label></div>
        <p className="gym-week-note">{TRAINING_WEEKS.find(item=>item.week===week)?.guidance} Las cargas nuevas las elegís vos; quedan guardadas para el mismo ejercicio y variante.</p>
        <div className="gym-routine-preview">{plannedExercises.map((item,index)=><button key={item.id} className="gym-preview-card" onClick={()=>setPreview(preview===item.id?null:item.id)} aria-expanded={preview===item.id}><div className="gym-preview-image"><img src={import.meta.env.BASE_URL+getTrainingIllustration(item.id)} alt="" width="240" height="130" loading="lazy"/><span>{String(index+1).padStart(2,'0')}</span></div><div><small>{item.primaryMuscle}</small><h3>{item.name}</h3><p>{item.targetSets} × {item.secondsTarget?`${item.secondsTarget} s`:`${item.repsMin}–${item.repsMax}`}<span>{item.restSeconds}s descanso</span></p>{item.hasWarmupSet&&<span className="gym-preview-warmup">+ S0 de aproximación</span>}{preview===item.id&&<p className="gym-preview-description">{item.instructions}</p>}</div></button>)}</div>
      </>}
    </>}
    {view==='history'&&<TrainingHistory sessions={sessions} historyExercise={historyExercise} setHistoryExercise={setHistoryExercise} onOpen={id=>{setSessionId(id);setExerciseCursor(null);setView('session');}}/>}
    {view==='custom'&&<><RoutineBuilder routines={routines} setRoutines={setRoutines} onUse={id=>{setRoutineId(id);setSessionId('');setView('session');}}/><LegacyImporter sessions={sessions} routines={routines} onImport={onImportLegacy}/></>}
    {correction&&canEditSession&&sessions[correction.sessionId]&&getDateAccess(sessions[correction.sessionId].date).canExecute&&<SavedSetCorrection session={sessions[correction.sessionId]} exerciseIndex={correction.exerciseIndex} setId={correction.setId} onClose={()=>setCorrection(null)} onSave={patch=>{if(!getDateAccess(selectedDate).canExecute||!getDateAccess(sessions[correction.sessionId]?.date??'').canExecute)return;setSessions(all=>{const original=all[correction.sessionId];if(!original||!canExecuteSession(original))return all;const exercise=original.exercises[correction.exerciseIndex];if(!exercise?.sets.some(set=>set.id===correction.setId&&set.completedAt!==null))return all;return {...all,[original.id]:{...original,exercises:original.exercises.map((item,index)=>index===correction.exerciseIndex?{...item,sets:item.sets.map(set=>set.id===correction.setId?{...set,...patch}:set)}:item)}};});setCorrection(null);setMessage('Serie corregida. Se conservan la fecha y la duración del entrenamiento.');}}/>}
    {endDialog&&session&&canEditSession&&<div className="modal-backdrop" onClick={()=>setEndDialog(null)}><section className="modal gym-end-modal" role="dialog" aria-modal="true" aria-labelledby="gym-end-title" onClick={e=>e.stopPropagation()}><button className="icon-button modal-close" aria-label="Cerrar" onClick={()=>setEndDialog(null)}><TrainingIcon name="close"/></button><p className="eyebrow">LO QUE HICISTE, CUENTA</p><h2 id="gym-end-title">{endDialog==='finish'?'¿Guardamos este entrenamiento?':'¿Lo dejamos por acá?'}</h2><p>{session.exercises.filter(e=>e.status==='done').length} ejercicios hechos · {summary?.completedSets??0} series registradas · {clock(getTrainingElapsed(session,now))}</p><p>Las series pendientes quedan pendientes. Tus registros, notas y cargas se conservan.</p><button className="button primary" onClick={finish}>{endDialog==='finish'?'Guardar y terminar':'Guardar como interrumpida'}</button><button className="button secondary" onClick={()=>setEndDialog(null)}>Seguir entrenando</button></section></div>}
  </div>;
}

function Tutorial({exercise,preview,setPreview}:{exercise:TrainingExerciseLog;preview:string|null;setPreview:(id:string|null)=>void}){
  const media=getTrainingMedia(exercise.exerciseId);
  const tutorial=exercise.variantId==='legacy-unspecified'?undefined:getTrainingTutorial(exercise.exerciseId,exercise.variantId)??media?.tutorials[0];
  if(!tutorial)return null;
  return <div className="gym-tutorial"><button onClick={()=>setPreview(preview===tutorial.id?null:tutorial.id)} aria-expanded={preview===tutorial.id}><span className="gym-play-circle"><TrainingIcon name="play" size={16}/></span><span><strong>Ver el movimiento</strong><small>{tutorial.languageLabel} · {tutorial.channel}</small></span><span>↗</span></button>{preview===tutorial.id&&<a className="gym-video-preview" href={tutorial.url} target="_blank" rel="noopener noreferrer"><img src={tutorial.thumbnail} alt={`Abrir tutorial: ${tutorial.title}`} width="480" height="270" loading="lazy"/><span><TrainingIcon name="play" size={20}/>Abrir en YouTube</span><small>{tutorial.title}</small></a>}</div>;
}

function PreviousLoad({previous}:{previous:ReturnType<typeof getPreviousExercise>}){
  if(!previous)return null;
  // The domain returns a dated exercise record; imported records may have unknown reps.
  const record=previous as unknown as {exercise?:TrainingExerciseLog;date?:string;session?:TrainingSession;sets?:TrainingExerciseLog['sets'];notes?:string};
  const item=record.exercise??record as unknown as TrainingExerciseLog;
  const sets=item.sets?.filter(s=>s.kind==='working'&&s.completedAt!==null)??[];
  if(!sets.length)return null;
  return <div className="gym-previous"><TrainingIcon name="chart" size={18}/><div><strong>La última vez{record.date?` · ${dateLabel(record.date)}`:''}</strong><span>{sets.map(s=>`${s.loadKg===null?'sin kg':`${s.loadKg} kg`}${s.reps!==null?` × ${s.reps}`:s.durationSeconds!==null?` · ${s.durationSeconds}s`:''}`).join('  ·  ')}</span>{item.notes&&<small>{item.notes}</small>}</div></div>;
}

function RestTimer({session,now,changeSession,beginRest,canEdit,exerciseIndex}:{session:TrainingSession;now:number;changeSession:(fn:(s:TrainingSession)=>TrainingSession)=>void;beginRest:(seconds:number)=>void;canEdit:boolean;exerciseIndex:number}){
  const [manual,setManual]=useState(90);
  const seconds=getRestRemaining(session,Math.max(now,Date.now()));
  const active=session.restUntil!==null||session.pausedRestSeconds!==null;
  return <section className={'gym-rest-card '+(active&&seconds===0?'is-ready':'')} aria-label="Temporizador de descanso"><div className="gym-panel-heading"><p className="eyebrow">RESPIRÁ. RECUPERÁ.</p><TrainingIcon name="clock" size={18}/></div><h3>Tu descanso</h3><div className="gym-rest-dial"><strong role="timer" aria-label={`${seconds} segundos de descanso`}>{clock(seconds)}</strong><small>{!canEdit?'Solo consulta':!active?'Al terminar una serie':seconds===0?'Listo para seguir':session.status==='paused'||session.restUntil===null?'En pausa':'Sin apuro'}</small></div><div className="gym-rest-buttons"><button className="button secondary" disabled={!canEdit||session.status==='paused'||!active||seconds===0} onClick={()=>changeSession(s=>s.restUntil!==null?{...s,pausedRestSeconds:getRestRemaining(s,Date.now()),restUntil:null}:{...s,restUntil:Date.now()+(s.pausedRestSeconds??0)*1000,pausedRestSeconds:null})}><TrainingIcon name={session.restUntil===null?'play':'pause'} size={16}/>{session.restUntil===null?'Seguir':'Pausar'}</button><button className="button secondary" disabled={!canEdit} onClick={()=>beginRest(session.exercises[exerciseIndex]?.restSeconds??90)}>Reiniciar</button><button className="button secondary" disabled={!canEdit||!active} onClick={()=>changeSession(s=>({...s,restUntil:null,pausedRestSeconds:null}))}>Saltar</button></div><div className="gym-quick-rests" aria-label="Elegir descanso">{[45,60,75,90,120].map(seconds=><button key={seconds} disabled={!canEdit} onClick={()=>beginRest(seconds)}>{seconds}s</button>)}</div><details className="gym-manual-rest"><summary>Otro tiempo</summary><label><span>Segundos</span><input aria-label="Descanso personalizado en segundos" type="number" min="1" max="3600" disabled={!canEdit} value={manual} onChange={e=>setManual(Math.max(1,Math.min(3600,Number(e.target.value))))}/><button className="button secondary" disabled={!canEdit} onClick={()=>beginRest(manual)}>Usar</button></label></details><p className="gym-timer-note">{canEdit?(isAndroidTrainingTimers()?'En la APK, los descansos y las series cronometradas avisan con la pantalla bloqueada o en segundo plano. Revisá los permisos y el volumen en Ajustes.':'El reloj conserva el tiempo al salir y volver. En la web, el aviso sonoro necesita esta pantalla abierta.'):'Los cronómetros se pueden usar únicamente en un entrenamiento de hoy.'}</p></section>;
}

function SetCountdown({session,exercise,now,changeSession}:{session:TrainingSession;exercise:TrainingExerciseLog;now:number;changeSession:(fn:(s:TrainingSession)=>TrainingSession)=>void}){
  const started=session.setTimerUntil!==null||session.pausedSetSeconds!==null;
  const remaining=started?getSetRemaining(session,Math.max(now,Date.now())):exercise.secondsTarget??30;
  const nextSet=exercise.sets.find(set=>set.completedAt===null);
  const running=session.setTimerUntil!==null&&remaining>0;
  return <section className="gym-set-countdown"><div><strong>Contador de la serie</strong><small>Al terminar, confirmá los segundos reales en la serie.</small></div><span role="timer">{clock(remaining)}</span><button className="button secondary" disabled={session.status==='paused'} onClick={()=>changeSession(s=>running?{...s,pausedSetSeconds:remaining,setTimerUntil:null}:startTrainingSetTimer(s,remaining||exercise.secondsTarget||30,Date.now()))}><TrainingIcon name={running?'pause':'play'} size={16}/>{running?'Pausar':'Iniciar'}</button><button className="text-button" onClick={()=>changeSession(s=>({...s,setTimerUntil:null,pausedSetSeconds:null}))}>Reiniciar</button>{started&&remaining===0&&nextSet&&<button className="button secondary" disabled={session.status==='paused'} onClick={()=>changeSession(s=>updateTrainingSet(s,s.currentExercise,nextSet.id,{durationSeconds:exercise.secondsTarget??30},Date.now()))}>Usar {exercise.secondsTarget??30}s en {nextSet.id.toUpperCase()}</button>}</section>;
}

function TrainingHistory({sessions,historyExercise,setHistoryExercise,onOpen}:{sessions:Sessions;historyExercise:string;setHistoryExercise:(id:string)=>void;onOpen:(id:string)=>void}){
  const all=Object.values(sessions).sort((a,b)=>b.startedAt-a.startedAt);
  const completed=all.filter(s=>s.status==='completed');
  const exercises=Array.from(new Map([...TRAINING_EXERCISES,...all.flatMap(s=>s.exercises.map(e=>({id:e.exerciseId,name:e.name})))].map(e=>[e.id,e])).values());
  const points=all.slice().reverse().flatMap(session=>session.exercises.filter(e=>e.exerciseId===historyExercise).map(exercise=>({session,exercise,loads:exercise.sets.filter(s=>s.kind==='working'&&s.completedAt!==null&&s.loadKg!==null).map(s=>s.loadKg!)}))).filter(item=>item.loads.length).slice(-10);
  const variants=[...new Set(points.map(p=>p.exercise.variantId))];
  const [variant,setVariant]=useState('');
  const chosenVariant=variants.includes(variant)?variant:variants.at(-1);
  const series=points.filter(p=>p.exercise.variantId===chosenVariant);const hasUnknownLoad=all.some(s=>s.status==='imported'&&s.exercises.some(e=>e.exerciseId===historyExercise&&e.sets.some(set=>set.loadKg!==null))); 
  const max=Math.max(...series.map(p=>Math.max(...p.loads)),1);
  const totalSets=all.reduce((sum,s)=>sum+s.exercises.reduce((sub,e)=>sub+e.sets.filter(set=>set.kind==='working'&&set.completedAt!==null).length,0),0);
  const rpes=all.filter(s=>s.status!=='imported').flatMap(s=>s.exercises.map(e=>e.rpe)).filter((n):n is number=>n!==null);
  const discomforts=all.filter(s=>s.status!=='imported').flatMap(s=>s.exercises.map(e=>e.discomfort)).filter((n):n is number=>n!==null);
  const avg=(values:number[])=>values.length?(values.reduce((a,b)=>a+b,0)/values.length).toFixed(1):'—';
  return <div className="gym-history"><div className="gym-metrics"><div><span>Sesiones finalizadas</span><strong>{completed.length}</strong></div><div><span>Series efectivas registradas</span><strong>{totalSets}</strong></div><div><span>Esfuerzo promedio</span><strong>{avg(rpes)}<small> / 10</small></strong></div><div><span>Molestia promedio</span><strong>{avg(discomforts)}<small> / 10</small></strong></div></div>
    <section className="gym-chart-panel"><div className="gym-panel-heading"><div><p className="eyebrow">PASO A PASO</p><h2>Lo que vas construyendo.</h2></div><TrainingIcon name="chart" size={25}/></div><label className="gym-chart-select"><span>Ejercicio</span><select value={historyExercise} onChange={e=>setHistoryExercise(e.target.value)}>{exercises.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</select></label>{variants.length>1&&<label className="gym-chart-select"><span>Variante</span><select value={chosenVariant} onChange={e=>setVariant(e.target.value)}>{variants.map(id=><option key={id} value={id}>{TRAINING_EXERCISES.find(e=>e.id===historyExercise)?.variants.find(v=>v.id===id)?.name??id}</option>)}</select></label>}
      {series.length?<><div className="gym-load-chart" role="img" aria-label={`Cargas máximas efectivas registradas: ${series.map(p=>`${dateLabel(p.session.date)}, ${Math.max(...p.loads)} kg`).join('; ')}`}><svg viewBox="0 0 600 180" preserveAspectRatio="none"><path className="gym-chart-grid" d="M20 25H580M20 85H580M20 145H580"/><polyline points={series.map((p,i)=>`${series.length===1?300:20+i*560/(series.length-1)},${145-Math.max(...p.loads)/max*115}`).join(' ')}/>{series.map((p,i)=><circle key={p.session.id} cx={series.length===1?300:20+i*560/(series.length-1)} cy={145-Math.max(...p.loads)/max*115} r="5"/>)}</svg></div><div className="gym-chart-caption"><span>{dateLabel(series[0].session.date)}</span><strong>{Math.max(...series.at(-1)!.loads)} kg · última vez</strong><span>{dateLabel(series.at(-1)!.session.date)}</span></div><div className="gym-load-records">{series.slice().reverse().map(p=><div key={p.session.id}><span>{dateLabel(p.session.date)}</span><strong>{p.exercise.sets.filter(s=>s.kind==='working'&&s.completedAt!==null).map(s=>`${s.loadKg??'—'} kg${s.reps!==null?` × ${s.reps}`:s.durationSeconds!==null?` · ${s.durationSeconds}s`:''}`).join(' · ')}</strong><small>{p.session.status==='imported'?'Importado · repeticiones no confirmadas':p.exercise.rpe!==null?`RPE ${p.exercise.rpe}`:''}</small></div>)}</div></>:<div className="gym-empty"><TrainingIcon name="chart" size={38}/><h3>Cada registro empieza algo.</h3><p>{hasUnknownLoad?'Tus cargas importadas están en el historial. El gráfico empieza con nuevas series de repeticiones confirmadas.':'Cuando completes series con carga, vas a ver acá tu evolución. La aproximación se mantiene separada.'}</p></div>}
    </section>
    <section className="gym-history-list"><div className="gym-panel-heading"><div><p className="eyebrow">TU HISTORIAL</p><h2>Un entrenamiento a la vez.</h2></div><span>{all.length} sesiones</span></div>{all.length?all.map(session=><button key={session.id} onClick={()=>onOpen(session.id)}><span className="gym-history-date"><strong>{session.status==='imported'?'↥':new Date(session.date+'T12:00:00').getDate()}</strong><small>{session.status==='imported'?'gym':new Date(session.date+'T12:00:00').toLocaleDateString('es-AR',{month:'short'})}</small></span><span><strong>{session.title}</strong><small>Semana {session.week} · {session.exercises.filter(e=>e.status==='done').length}/{session.exercises.length} ejercicios · {statusLabel[session.status]}</small></span><span>↗</span></button>):<p className="gym-muted">Todavía no hay sesiones registradas. Tu rutina ya está lista para empezar.</p>}</section>
    <section className="gym-weekly-stats"><p className="eyebrow">LAS CUATRO SEMANAS DE TU PLAN</p><h2>Tu recorrido por bloques.</h2><div>{TRAINING_WEEKS.map(week=>{const records=all.filter(s=>s.week===week.week&&s.status!=='imported');const done=records.flatMap(s=>s.exercises).filter(e=>e.status==='done').length;const total=records.reduce((sum,s)=>sum+s.exercises.length,0);return <article key={week.week}><span>Semana {week.week}</span><strong>{done}/{total}</strong><small>ejercicios hechos en sesiones registradas</small><div><i style={{width:`${total?done/total*100:0}%`}}/></div></article>;})}</div><p className="gym-muted">El reporte semanal de Mi Vida incluye las series reales, las cargas y tus sensaciones. Un día marcado en la agenda por sí solo no se cuenta como entrenamiento realizado.</p></section>
  </div>;
}

const emptyCustom=()=>({name:'',primaryMuscle:'',secondaryMuscles:'',targetSets:3,repsMin:10,repsMax:12,secondsTarget:'',restSeconds:60,hasWarmupSet:false,instructions:''});
function LegacyImporter({sessions,routines,onImport}:{sessions:Sessions;routines:Routines;onImport?: (result:LegacyTrainingImport)=>void}){
  const [pending,setPending]=useState<ReturnType<typeof importLegacyTraining>|null>(null);
  const [message,setMessage]=useState('');
  async function readFile(file:File|undefined){if(!file)return;setPending(null);setMessage('');if(file.size>5*1024*1024){setMessage('El archivo supera 5 MB. Elegí el respaldo JSON del gym.');return;}try{const result=importLegacyTraining(await file.text());setPending(result);}catch(error){setMessage(error instanceof Error?error.message:'No se pudo leer el respaldo.');}}
  function apply(){if(!pending||!onImport)return;onImport(pending);setMessage('Los registros se agregaron. Tus entrenamientos actuales se conservaron.');setPending(null);}
  return <section className="gym-legacy-import"><details><summary>Traer registros de la app anterior</summary><p>Si tenés un respaldo JSON de Plan Gym, podés sumar sus cargas, sensaciones y rutinas personales. Android mantiene separados los datos de cada app.</p><label className="button secondary gym-import-button">Elegir respaldo JSON<input type="file" accept=".json,application/json" aria-label="Elegir respaldo JSON del gym anterior" onChange={e=>{void readFile(e.target.files?.[0]);e.target.value='';}}/></label>{pending&&<div className="gym-import-preview"><strong>{Object.keys(pending.sessions).filter(id=>!sessions[id]).length} registros y {Object.keys(pending.routines).filter(id=>!routines[id]).length} rutinas para agregar</strong>{pending.warnings.map((warning,index)=><p key={index}>{warning}</p>)}<button className="button primary" disabled={!onImport} onClick={apply}>Agregar a Mi Vida.</button><button className="text-button" onClick={()=>setPending(null)}>Cancelar</button></div>}{message&&<p role="status">{message}</p>}</details></section>;
}
function RoutineBuilder({routines,setRoutines,onUse}:{routines:Routines;setRoutines:Dispatch<SetStateAction<Routines>>;onUse:(id:string)=>void}){
  const [name,setName]=useState('');const [day,setDay]=useState<1|2|3>(1);const [draft,setDraft]=useState(emptyCustom);const [exercises,setExercises]=useState<TrainingExerciseDefinition[]>([]);const [notice,setNotice]=useState('');
  function addExercise(){
    if(!draft.name.trim()||!draft.primaryMuscle.trim()){setNotice('Poné el nombre y el grupo muscular para agregarlo.');return;}
    if(exercises.length>=30){setNotice('La rutina puede tener hasta 30 ejercicios.');return;}
    const validInteger=(n:number,min:number,max:number)=>Number.isInteger(n)&&n>=min&&n<=max;
    const seconds=draft.secondsTarget===''?null:Number(draft.secondsTarget);
    if(!validInteger(draft.targetSets,1,4)||!validInteger(draft.restSeconds,0,3600)||!validInteger(draft.repsMin,1,1000)||!validInteger(draft.repsMax,draft.repsMin,1000)||(seconds!==null&&!validInteger(seconds,1,7200))){setNotice('Revisá series, repeticiones y tiempos: usá números enteros y un máximo de repeticiones igual o mayor al mínimo.');return;}
    const id=newId('custom-exercise');setExercises(all=>[...all,{...draft,id,day,order:all.length+1,name:draft.name.trim(),primaryMuscle:draft.primaryMuscle.trim(),secondaryMuscles:draft.secondaryMuscles.trim(),secondsTarget:seconds,restLabel:draft.restSeconds+' s',variants:[{id:'custom',name:draft.name.trim()}]}]);setDraft(emptyCustom());setNotice('');
  }
  function save(){
    if(!name.trim()||!exercises.length){setNotice('Dale un nombre y agregá al menos un ejercicio.');return;}
    const id=newId('routine');const routine=normalizeTrainingRoutine({id,name:name.trim(),day,createdAt:Date.now(),exercises:exercises.map((item,index)=>({...item,day,order:index+1}))},id);
    if(!routine){setNotice('Hay un dato de la rutina para revisar. Corregilo antes de guardar.');return;}
    setRoutines(all=>({...all,[id]:routine}));setName('');setExercises([]);setNotice('Rutina guardada y disponible en Entrenar.');
  }

  return <><section className="gym-custom-intro"><p className="eyebrow">TU MANERA DE ENTRENAR</p><h2>Hacé lugar para otra rutina.</h2><p>Conservás tu plan original y podés sumar sesiones propias, con la misma guía de series, cargas y descansos.</p></section><div className="gym-builder-grid"><section className="gym-builder"><div className="gym-builder-fields"><label><span>Nombre de la rutina</span><input maxLength={120} value={name} onChange={e=>setName(e.target.value)} placeholder="Por ejemplo, movilidad y core"/></label><label><span>Bloque</span><select value={day} onChange={e=>setDay(Number(e.target.value) as typeof day)}>{TRAINING_DAYS.map(item=><option key={item.day} value={item.day}>{item.title}</option>)}</select></label></div><h3>Sumar un ejercicio</h3><div className="gym-builder-fields"><label><span>Ejercicio</span><input maxLength={180} value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})}/></label><label><span>Músculo principal</span><input maxLength={180} value={draft.primaryMuscle} onChange={e=>setDraft({...draft,primaryMuscle:e.target.value})}/></label><label className="gym-full"><span>Músculos secundarios</span><input maxLength={300} value={draft.secondaryMuscles} onChange={e=>setDraft({...draft,secondaryMuscles:e.target.value})}/></label><label><span>Series efectivas</span><input type="number" min="1" max="4" value={draft.targetSets} onChange={e=>setDraft({...draft,targetSets:Math.max(1,Math.min(4,Number(e.target.value)))})}/></label><label><span>Descanso · segundos</span><input type="number" min="0" max="3600" value={draft.restSeconds} onChange={e=>setDraft({...draft,restSeconds:Math.max(0,Math.min(3600,Number(e.target.value)))})}/></label><label><span>Repeticiones mínimas</span><input type="number" min="1" max="1000" value={draft.repsMin} onChange={e=>setDraft({...draft,repsMin:Math.max(1,Number(e.target.value))})}/></label><label><span>Repeticiones máximas</span><input type="number" min="1" max="1000" value={draft.repsMax} onChange={e=>setDraft({...draft,repsMax:Math.max(1,Number(e.target.value))})}/></label><label className="gym-full"><span>O duración por serie · segundos (opcional)</span><input type="number" min="1" max="7200" placeholder="Dejá vacío para contar repeticiones" value={draft.secondsTarget} onChange={e=>setDraft({...draft,secondsTarget:e.target.value})}/></label><label className="gym-full gym-builder-checkbox"><input type="checkbox" checked={draft.hasWarmupSet} onChange={e=>setDraft({...draft,hasWarmupSet:e.target.checked})}/><span>Primero, una S0 de aproximación moderada</span></label><label className="gym-full"><span>Indicaciones de técnica</span><textarea rows={2} maxLength={3000} value={draft.instructions} onChange={e=>setDraft({...draft,instructions:e.target.value})}/></label></div><button className="button secondary" onClick={addExercise}><TrainingIcon name="plus" size={17}/>Agregar ejercicio</button>{notice&&<p className="gym-builder-notice" role="status">{notice}</p>}{exercises.length>0&&<div className="gym-draft-list">{exercises.map((exercise,index)=><div key={exercise.id}><span>{index+1}</span><strong>{exercise.name}<small>{exercise.targetSets} series · {exercise.restSeconds}s descanso</small></strong><button aria-label={`Quitar ${exercise.name}`} onClick={()=>setExercises(all=>all.filter(e=>e.id!==exercise.id))}><TrainingIcon name="close" size={16}/></button></div>)}</div>}<button className="button primary gym-save-routine" onClick={save}>Guardar rutina<TrainingIcon name="check" size={17}/></button></section><section className="gym-saved-routines"><p className="eyebrow">TUS RUTINAS PERSONALES</p><h2>Listas para volver.</h2>{Object.values(routines).length?Object.values(routines).map(routine=><article key={routine.id}><span className="gym-routine-symbol"><TrainingIcon name="gym" size={24}/></span><h3>{routine.name}</h3><p>{routine.exercises.length} ejercicios · {TRAINING_DAYS.find(d=>d.day===routine.day)?.title}</p><button className="button secondary" onClick={()=>onUse(routine.id)}>Elegir rutina<TrainingIcon name="arrow" size={16}/></button></article>):<div className="gym-empty"><TrainingIcon name="plus" size={35}/><p>Las rutinas que guardes aparecen acá. El plan original sigue disponible en Entrenar.</p></div>}</section></div></>;
}

function SavedSetCorrection({session,exerciseIndex,setId,onClose,onSave}:{session:TrainingSession;exerciseIndex:number;setId:string;onClose:()=>void;onSave:(patch:{loadKg:number|null;reps?:number;durationSeconds?:number})=>void}){
  const exercise=session.exercises[exerciseIndex];const set=exercise.sets.find(item=>item.id===setId)!;const timed=isTimedTrainingExercise(exercise);
  const [load,setLoad]=useState(set.loadKg===null?'':String(set.loadKg));const [count,setCount]=useState(String((timed?set.durationSeconds:set.reps)??''));const [error,setError]=useState('');
  function save(event:React.FormEvent){event.preventDefault();const kg=load.trim()===''?null:Number(load);const amount=Number(count);if((kg!==null&&(!Number.isFinite(kg)||kg<0||kg>1500))||!Number.isInteger(amount)||amount<=0||amount>(timed?7200:1000)){setError('Revisá la carga y usá una cantidad entera mayor a cero.');return;}onSave({loadKg:kg,...(timed?{durationSeconds:amount}:{reps:amount})});}
  return <div className="modal-backdrop" onClick={onClose}><section className="modal gym-end-modal" role="dialog" aria-modal="true" aria-labelledby="gym-correction-title" onClick={event=>event.stopPropagation()}><button className="icon-button modal-close" aria-label="Cerrar corrección" onClick={onClose}><TrainingIcon name="close"/></button><p className="eyebrow">UN AJUSTE EN TU REGISTRO</p><h2 id="gym-correction-title">Corregir {setId.toUpperCase()}</h2><p>{exercise.name}. La fecha, el estado y la duración de la sesión se conservan.</p><form onSubmit={save}><div className="gym-feedback"><label><span>Carga · kg</span><input autoFocus type="number" inputMode="decimal" min="0" max="1500" step="0.5" value={load} onChange={event=>setLoad(event.target.value)}/></label><label><span>{timed?'Segundos reales':'Repeticiones reales'}</span><input required type="number" inputMode="numeric" min="1" max={timed?7200:1000} step="1" value={count} onChange={event=>setCount(event.target.value)}/></label></div>{error&&<p role="alert">{error}</p>}<button className="button primary" type="submit">Guardar corrección</button><button className="button secondary" type="button" onClick={onClose}>Cancelar</button></form></section></div>;
}
